import React, { memo, useState } from 'react';
import { ClearAll } from '@mui/icons-material';
import userStore from '../../../../core/stores/userStore';
import Action from './Action';
import tabStore from '../../../../core/stores/tabStore';
import snapshotStore from '../../../../core/stores/snapshotStore';
import { sendRuntimeMessage } from '../../../../core/browers/runtime';
import { Dialog, DialogTitle, DialogContent, DialogActions, Button, Typography, FormGroup, FormControlLabel, Checkbox } from '@mui/material';
import { useTranslation } from 'react-i18next';

const ActionClearTabs = () => {
    const { t } = useTranslation();
    const [confirmOpen, setConfirmOpen] = useState(false);
    const [options, setOptions] = useState({});
    const showLabel = userStore(state => state.settings.bottomNavOptions.showLabel && state.settings.bottomNavOptions.navs.find(nav => nav.name === 'clearTabs')?.showLabel);

    // 获取必要的 store 数据
    const { onlyCurrentWindowTabs, clearTabsBtn, updateSetting } = userStore((state) => ({
        onlyCurrentWindowTabs: state.settings.onlyCurrentWindowTabs,
        clearTabsBtn: state.settings.clearTabsBtn,
        updateSetting: state.updateSetting
    }));
    const { currentWindow } = tabStore((state) => ({
        currentWindow: state.currentWindow
    }));

    const clearTabs = async (options) => {
        if (options.createSnapshot) {
            await snapshotStore.getState().addSnapshot();
        }
        await sendRuntimeMessage("clear_tabs", {
            windowId: onlyCurrentWindowTabs ? currentWindow.id : 0,
            options: options
        });
        setConfirmOpen(false);
    };

    const handleClick = async () => {
        if (clearTabsBtn.options.confirm) {
            setOptions(clearTabsBtn.options);
            setConfirmOpen(true);
        } else {
            await clearTabs(clearTabsBtn.options);
        }
    };

    const handleOptionChange = (key) => async (event) => {
        const newOptions = { ...options, [key]: event.target.checked };
        setOptions(newOptions);
        // 添加更新设置的功能
        await updateSetting('clearTabsBtn', {
            ...clearTabsBtn,
            options: newOptions
        });
    };

    return (
        <React.Fragment>
            <Action
                icon={<ClearAll />}
                labelKey="options:settings.appearance.bottomNav.clearTabs"
                showLabel={showLabel}
                handleClick={handleClick}
            />
            <Dialog open={confirmOpen} onClose={() => setConfirmOpen(false)}>
                <DialogTitle variant="h3">{t('options:settings.appearance.clearTabsBtn.confirmClearTabs')}</DialogTitle>
                <DialogContent>
                    <Typography gutterBottom>{t('options:settings.appearance.clearTabsBtn.confirmClearTabsMessage')}</Typography>
                    <FormGroup>
                        <FormControlLabel
                            control={<Checkbox
                                checked={options.createSnapshot || false}
                                onChange={handleOptionChange('createSnapshot')}
                            />}
                            label={t('options:settings.appearance.clearTabsBtn.options.createSnapshot')}
                        />
                        <FormControlLabel
                            control={<Checkbox
                                checked={options.closeInactiveTabs || false}
                                onChange={handleOptionChange('closeInactiveTabs')}
                            />}
                            label={t('options:settings.appearance.clearTabsBtn.options.closeInactiveTabs')}
                        />
                        <FormControlLabel
                            control={<Checkbox
                                checked={options.closeDiscardTabs || false}
                                onChange={handleOptionChange('closeDiscardTabs')}
                            />}
                            label={t('options:settings.appearance.clearTabsBtn.options.closeDiscardTabs')}
                        />
                        <FormControlLabel
                            control={<Checkbox
                                checked={options.skipSoundTabs || false}
                                onChange={handleOptionChange('skipSoundTabs')}
                            />}
                            label={t('options:settings.appearance.clearTabsBtn.options.skipSoundTabs')}
                        />
                        <FormControlLabel
                            control={<Checkbox
                                checked={options.skipCurrentTab || false}
                                onChange={handleOptionChange('skipCurrentTab')}
                            />}
                            label={t('options:settings.appearance.clearTabsBtn.options.skipCurrentTab')}
                        />
                    </FormGroup>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setConfirmOpen(false)} color="primary">
                        {t('options:settings.appearance.clearTabsBtn.cancel')}
                    </Button>
                    <Button onClick={() => clearTabs(options)} color="error" autoFocus>
                        {t('options:settings.appearance.clearTabsBtn.confirm')}
                    </Button>
                </DialogActions>
            </Dialog>
        </React.Fragment>
    );
};

export default memo(ActionClearTabs);
