import React, { memo } from "react";
import { Close } from "@mui/icons-material";
import { IconButton, Tooltip, Typography } from "@mui/material";
import { removeTabById } from "../../../../core/browers/tabs";
import { useTranslationContext } from "../../../Providers/TranslationProvider";
import { useSettingsContext } from "../../../Providers/SettingsProvider";
import { Refresh } from "@mui/icons-material";



const TabRefresh = ({ tabId }) => {
  const { t } = useTranslationContext();

  const settings = useSettingsContext();

  const handleClick = async (event) => {
    event.stopPropagation();
    await chrome.tabs.reload(tabId);
  };

  return (
    <Tooltip arrow placement="top" title={<Typography>{t('tabMenu.Reload')}</Typography>} aria-label={t('tabMenu.Reload')}>
      <IconButton className="close-button" sx={{ padding: "4px", color: "inherit", display: settings.AlwaysShowCloseButton ? "flex" : "none" }} onClick={handleClick}>
        <Refresh size="small" />
      </IconButton>
    </Tooltip>
  );
};

export default memo(TabRefresh);
