import { IconButton, Tooltip, Typography } from "@mui/material";
import React, { memo } from "react";
import { sendTabMessage } from "../../../../core/browers/runtime";
import { useTranslationContext } from "../../../Providers/TranslationProvider";
import { AddAPhoto } from "@mui/icons-material";
import snapshotStore from "../../../../core/stores/snapshotStore";


const CreateSnapshotIconBtn = ({ tabId }) => {
  const { t } = useTranslationContext();

  const handleClick = async () => {
    try {
      await snapshotStore.getState().addSnapshot();
      toast.success(t('createSnapshotSuccess'));
    } catch (error) {
      console.error('addSnapshot error', error)
      toast.error(t('createSnapshotFailed'));
    }
  };


  return (
    <Tooltip arrow placement="top" title={<Typography>{t('createSnapshot')}</Typography>}>
      <IconButton sx={{ padding: "4px", color: "inherit" }} onClick={handleClick}>
        <AddAPhoto sx={{ fontSize: "1rem", color: "inherit" }} />
      </IconButton>
    </Tooltip>
  );
};

export default memo(CreateSnapshotIconBtn);
