import { IconButton, Tooltip, Typography } from "@mui/material";
import React, { memo } from "react";
import { useTranslationContext } from "../../../Providers/TranslationProvider";
import { ArrowBack } from "@mui/icons-material";
import tabStore from "../../../../core/stores/tabStore";

const TabGoBack = memo(({ tabId }) => {
  const { t } = useTranslationContext();

  const isCouldGoBack = tabStore(state =>
    state.tabs.find(t => t.id === tabId)?.navigationState?.canGoBack
  );

  const handleClick = async (event) => {
    event.preventDefault();
    event.stopPropagation();
    try {
      await chrome.tabs.goBack(tabId);
    } catch (error) {
      console.error('Error going back:', error);
    }
  };

  return (
    <Tooltip arrow placement="top" title={<Typography>{t('clickToGoBack')}</Typography>}>
      <span>
        <IconButton
          sx={{ padding: "4px", color: "inherit" }}
          onClick={handleClick}
          disabled={!isCouldGoBack}
          size="small"
        >
          <ArrowBack fontSize="small" />
        </IconButton>
      </span>
    </Tooltip>
  );
});

export default TabGoBack;
