import React, { useState, forwardRef } from "react";
import { MenuItem, ListItemText, Typography, Button, Dialog, AppBar, Toolbar, IconButton, Slide, Box, TextField, Stack, CircularProgress, Backdrop, FormControlLabel, Switch } from "@mui/material";
import { Close, Add, Circle, RadioButtonChecked } from "@mui/icons-material";
import { faviconURL } from "../../../../../utils/helpers";
import * as Sentry from "@sentry/react";
import { useTranslationContext } from "../../../../Providers/TranslationProvider";
import { chromeGroupAvailableColors } from "../../../../../utils/colors";
import quickAccessStore from "../../../../../core/stores/quickAccessStore";

const Transition = forwardRef(function Transition(props, ref) {
    return <Slide direction="up" ref={ref} {...props} />;
});

export default function Edit({ uuid, onSelect }) {
    const { t } = useTranslationContext();
    const { shortcut, setQuickAccess, removeQuickAccess } = quickAccessStore(state => ({
        shortcut: state.quickAccess.find(shortcut => shortcut.uuid === uuid),
        setQuickAccess: state.setQuickAccess,
        removeQuickAccess: state.removeQuickAccess
    }));

    const [open, setOpen] = useState(false);
    const [urls, setUrls] = useState(shortcut.urls?.length ? shortcut.urls?.map(u => ({ url: u.url, title: u.title })) : [{ url: shortcut.url, title: shortcut.title }]);
    const [loading, setLoading] = useState(false);
    const [title, setTitle] = useState(shortcut.title);
    const [color, setColor] = useState(shortcut.color || "");
    const [shortName, setShortName] = useState(shortcut.short_name || "");

    const handleClickOpen = () => setOpen(true);
    const handleClose = () => {
        setOpen(false);
        if (typeof onSelect === 'function') {
            onSelect();
        }
    };

    const handleFormSubmit = async (event) => {
        event.preventDefault();
        setLoading(true);
        const formJson = {
            title,
            short_name: shortName,
            color,
        };

        try {
            const validUrls = urls.filter(u => u.url.trim() !== "");

            if (validUrls.length === 0) {
                // If no valid URLs, delete the shortcut
                removeQuickAccess(uuid);
                handleClose();
                return;
            } else if (validUrls.length === 1) {
                const singleUrl = validUrls[0];
                formJson.favIconUrl = faviconURL(singleUrl.url);
                formJson.url = singleUrl.url;
                formJson.title = singleUrl.title;
                formJson.urls = [];
            } else {
                // Multiple URLs case
                formJson.urls = await Promise.all(validUrls.map(async (u) => ({
                    url: u.url,
                    title: u.title,
                    favIconUrl: faviconURL(u.url)
                })));
            }

            setQuickAccess(uuid, { ...shortcut, ...formJson });
            handleClose();
        } catch (error) {
            Sentry.captureException(error);
        } finally {
            setLoading(false);
        }
    };

    const handleDragStart = (event) => event.stopPropagation();

    const handleUrlChange = (index, event) => {
        const newUrls = [...urls];
        newUrls[index].url = event.target.value;
        setUrls(newUrls);
    };

    const handleTitleChange = (index, event) => {
        const newUrls = [...urls];
        newUrls[index].title = event.target.value;
        setUrls(newUrls);
    };

    const handleAddUrl = async () => {
        const currentTab = await chrome.tabs.query({ active: true, currentWindow: true });
        if (currentTab && currentTab[0]) {
            setUrls([...urls, { url: currentTab[0].url, title: currentTab[0].title || "" }]);
        } else {
            setUrls([...urls, { url: "", title: "" }]);
        }
    };

    const handleRemoveUrl = (index) => setUrls(urls.filter((_, i) => i !== index));

    return (
        <React.Fragment>
            <MenuItem onClick={handleClickOpen}>
                <ListItemText>
                    <Typography variant="body1">{t("Edit")}</Typography>
                </ListItemText>
            </MenuItem>
            <Dialog
                fullScreen
                open={open}
                onClose={handleClose}
                TransitionComponent={Transition}
                PaperProps={{
                    component: 'form',
                    onSubmit: handleFormSubmit,
                }}
            >
                <AppBar sx={{ position: 'relative' }}>
                    <Toolbar>
                        <IconButton
                            edge="start"
                            color="inherit"
                            onClick={handleClose}
                            aria-label="close"
                        >
                            <Close />
                        </IconButton>
                        <Typography sx={{ ml: 2, flex: 1 }} variant="h6" component="div">
                            {t('cancel')}
                        </Typography>
                        <Button type="submit" color="inherit" disabled={loading}>
                            {t('Save')}
                        </Button>
                    </Toolbar>
                </AppBar>
                <Box sx={{ p: 2 }}>
                    <Stack spacing={2} direction="column">
                        <TextField
                            fullWidth
                            name="title"
                            label={t("Name")}
                            multiline
                            defaultValue={shortcut.title}
                            onMouseDown={handleDragStart}
                            onChange={(e) => setTitle(e.target.value)}
                        />
                        {urls.length > 1 && <>
                            <TextField
                                fullWidth
                                name="short_name"
                                label={t("shortName")}
                                inputProps={{ maxLength: 6 }}
                                value={shortName}
                                onChange={(e) => setShortName(e.target.value)}
                            />
                            <Stack direction="row">
                                {chromeGroupAvailableColors.map(colorInfo => (
                                    <IconButton
                                        fontSize="16px"
                                        key={colorInfo.color}
                                        onClick={() => setColor(colorInfo.color)}
                                    >
                                        {color === colorInfo.color ? (
                                            <RadioButtonChecked sx={{ color: colorInfo.hex, fontSize: "14px" }} />
                                        ) : (
                                            <Circle sx={{ color: colorInfo.hex, fontSize: "14px" }} />
                                        )}
                                    </IconButton>
                                ))}
                            </Stack>
                        </>}
                        {urls.map((url, index) => (
                            <Stack key={index} direction="row" alignItems="center" justifyContent="space-between">
                                <Box sx={{ border: '1px solid #ccc', p: 2, mb: 2 }}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        name={`title-${index}`}
                                        label={t("title")}
                                        multiline
                                        value={url.title}
                                        onChange={(event) => handleTitleChange(index, event)}
                                        onMouseDown={handleDragStart}
                                        sx={{ mb: 2 }}
                                    />
                                    <TextField
                                        fullWidth
                                        size="small"
                                        name={`url-${index}`}
                                        label={t("URL")}
                                        multiline
                                        value={url.url}
                                        onChange={(event) => handleUrlChange(index, event)}
                                        onMouseDown={handleDragStart}
                                        sx={{ mb: 1 }}
                                    />
                                </Box>
                                <IconButton onClick={() => handleRemoveUrl(index)}>
                                    <Close />
                                </IconButton>
                            </Stack>
                        ))}
                        <Button onClick={handleAddUrl} startIcon={<Add />}>
                            {t("Add URL")}
                        </Button>
                    </Stack>
                </Box>
                <Backdrop
                    sx={{ color: '#fff', zIndex: (theme) => theme.zIndex.drawer + 1 }}
                    open={loading}
                >
                    <CircularProgress color="inherit" />
                </Backdrop>
            </Dialog>
        </React.Fragment>
    );
}